<?php elseif($type==='users'): ?><td><strong><?= htmlspecialchars($item['name']) ?></strong><br><small>Créé le <?= date('d/m/Y',strtotime($item['created_at'])) ?></small></td><td><?= htmlspecialchars($item['email']) ?><br><small><?= htmlspecialchars($item['phone']??'—') ?></small></td><td><?= $item['role']==='instructor'?'Formateur':($item['role']==='admin'?'Administrateur':'Apprenant') ?></td><td><span class="status <?= $item['status']==='active'?'published':'draft' ?>"><?= $item['status']==='active'?'Actif':'OTP en attente' ?></span></td><td><a class="btn secondary" href="/admin/utilisateurs/modifier?id=<?= (int)$item['id'] ?>">Gérer</a></td>
<?php else: ?><td><strong><?= htmlspecialchars($item['title']) ?></strong><br><small><?= htmlspecialchars($item['reference']) ?> · <?= $item['product_type']==='digital'?'Numérique':'Physique' ?></small></td><td><?= htmlspecialchars($item['category']) ?></td><td><?php if($item['product_type']==='digital'): ?><span class="status published">∞ Téléchargement</span><?php else: ?><div class="stock-cell"><strong class="stock-number <?= (int)$item['stock_quantity']===0?'empty':((int)$item['stock_quantity']<=(int)$item['low_stock_threshold']?'low':'') ?>"><?= (int)$item['stock_quantity'] ?></strong><small><?= (int)$item['stock_quantity']===0?'Rupture':((int)$item['stock_quantity']<=(int)$item['low_stock_threshold']?'Stock faible':'Disponible') ?></small></div><?php endif ?></td><td><?= $item['promotional_price']!==null?'<strong>'.number_format($item['promotional_price'],0,',',' ').' F</strong>':($item['price']?number_format($item['price'],0,',',' ').' F':'Sur devis') ?></td><td><span class="status <?= $item['status']==='published'?'published':'draft' ?>"><?= htmlspecialchars($item['status']) ?></span></td><td><div class="table-actions"><?php if($item['product_type']!=='digital'): ?><button class="btn primary" type="button" data-stock-toggle="<?= (int)$item['id'] ?>">± Stock</button><?php endif ?><a class="btn secondary" href="/admin/produits/modifier?id=<?= (int)$item['id'] ?>">Modifier</a></div><?php if($item['product_type']!=='digital'): ?><form class="stock-adjust-form" data-stock-form="<?= (int)$item['id'] ?>" method="post" action="/admin/produits/stock" hidden><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><select name="mode"><option value="in">Entrée</option><option value="out">Sortie</option><option value="set">Inventaire réel</option></select><input type="number" name="quantity" min="0" required placeholder="Qté"><input name="note" placeholder="Motif / fournisseur"><button class="btn primary">Valider</button></form><?php endif ?></td><?php endif ?>
