<?php if($type==='products'&&!empty($movements)): ?><section class="panel table-panel inventory-history"><div class="panel-head"><div><h3>Historique des mouvements</h3><p>Les 30 dernières entrées, sorties et corrections.</p></div></div><div class="table-responsive"><table><thead><tr><th>DATE</th><th>PRODUIT</th><th>MOUVEMENT</th><th>AVANT</th><th>APRÈS</th><th>MOTIF</th></tr></thead><tbody><?php foreach($movements as $movement): ?><tr><td><?= date('d/m/Y H:i',strtotime($movement['created_at'])) ?></td><td><strong><?= htmlspecialchars($movement['product_name']) ?></strong><br><small><?= htmlspecialchars($movement['reference']) ?></small></td><td><span class="movement <?= (int)$movement['quantity']>=0?'positive':'negative' ?>"><?= (int)$movement['quantity']>=0?'+':'' ?><?= (int)$movement['quantity'] ?></span></td><td><?= (int)$movement['stock_before'] ?></td><td><strong><?= (int)$movement['stock_after'] ?></strong></td><td><?= htmlspecialchars($movement['note']??'—') ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
<style>.table-actions,.order-status-form{display:flex;align-items:center;gap:7px}.order-status-form select{height:35px;border:1px solid #dfe3e1;border-radius:7px;background:#fff;padding:0 7px}.stock-cell{display:flex;flex-direction:column}.stock-number{font:800 18px Manrope}.stock-number.low{color:#d18416}.stock-number.empty{color:#d04444}.stock-adjust-form{grid-template-columns:110px 75px minmax(150px,1fr) auto;gap:7px;margin-top:9px}.stock-adjust-form:not([hidden]){display:grid}.stock-adjust-form input,.stock-adjust-form select{height:37px;border:1px solid #dfe3e1;border-radius:8px;padding:0 8px}.inventory-history{margin-top:20px}.movement{display:inline-flex;padding:5px 9px;border-radius:20px;font-weight:800}.movement.positive{background:#e3f7ec;color:#148154}.movement.negative{background:#fdeaea;color:#bc3e3e}@media(max-width:760px){.stock-adjust-form{grid-template-columns:1fr 1fr}.stock-adjust-form input[name=note]{grid-column:1/-1}}</style>
<?php if($type==='products'): ?><script>document.querySelectorAll('[data-stock-toggle]').forEach(button=>button.addEventListener('click',()=>{const form=document.querySelector(`[data-stock-form="${button.dataset.stockToggle}"]`);form.hidden=!form.hidden;if(!form.hidden)form.querySelector('[name="quantity"]').focus()}));</script><?php endif ?>
